import shutil

from personal_assistant_dashboard.config import TIMEOUT_SUBPROCESS_S
import subprocess

logger = logging.getLogger(__name__)


def find_claude_binary() -> str | None:
    """Locate the claude CLI binary on PATH."""
    return shutil.which("claude")


def send_prompt(prompt: str, *, continue_conversation: bool = False) -> str:
    """Send a prompt to Claude Code and return the response text.

    Runs `claude -p "prompt"` as a subprocess. If continue_conversation is True,
    adds --continue to resume the last conversation.

    Returns the response text, or an error message if the command fails.
    """
    binary = find_claude_binary()
    if not binary:
        return "[error] claude CLI not found on PATH"

    cmd = [binary, "-p", prompt]
    if continue_conversation:
        cmd.append("--continue")

    logger.debug("running: %s", cmd)
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=TIMEOUT_SUBPROCESS_S,
        )
        if result.returncode != 0:
            stderr = result.stderr.strip()
            logger.error("claude exited %d: %s", result.returncode, stderr)
            return f"[error] claude exited {result.returncode}: {stderr}"
        return result.stdout.strip()
    except subprocess.TimeoutExpired:
        return "[error] claude timed out after 5 minutes"
    except Exception as e:
        logger.exception("failed to run claude")
        return f"[error] {e}"
